Evaluate the JavaScript Conway's Game of Life implementation. 

Solution A: function runConwayGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = canvas.height = 500;
    const ctx = canvas.getContext('2d');

    const w = 500, h = 500, cellSize = 10, rows = h / cellSize, cols = w / cellSize;
    const emojis = ['🟩', '🟨', '🟧', '🟥', '💀'];
    const getEmoji = age => {
        if (age < 2) return emojis[0];
        if (age < 4) return emojis[1];
        if (age < 6) return emojis[2];
        if (age < 8) return emojis[3];
        return emojis[4];
    };

    let grid = Array.from({ length: rows }, () => Array(cols).fill(null));
    let fadeGrid = Array.from({ length: rows }, () => Array(cols).fill(0));

    const createUI = () => {
        const container = document.createElement('div');
        container.style.marginBottom = '10px';

        const patternSelect = document.createElement('select');
        const patterns = ['Glider', 'Blinker', 'Pulsar', 'Gosper Gun'];
        patterns.forEach(p => {
            const opt = document.createElement('option');
            opt.value = p.toLowerCase().replace(/ /g, '');
            opt.textContent = p;
            patternSelect.appendChild(opt);
        });
        patternSelect.addEventListener('change', () => setPattern(patternSelect.value));
        container.appendChild(patternSelect);

        const speedLabel = document.createElement('label');
        speedLabel.textContent = ' Speed (gens/sec): ';
        const speedSlider = document.createElement('input');
        speedSlider.type = 'range';
        speedSlider.min = '1';
        speedSlider.max = '10';
        speedSlider.value = '5';
        speedSlider.addEventListener('input', () => { msPerGen = 1000 / speedSlider.value; });
        speedLabel.appendChild(speedSlider);
        container.appendChild(speedLabel);

        const randomBtn = document.createElement('button');
        randomBtn.textContent = 'Randomize';
        randomBtn.onclick = randomize;
        container.appendChild(randomBtn);

        const clearBtn = document.createElement('button');
        clearBtn.textContent = 'Clear';
        clearBtn.onclick = clearGrid;
        container.appendChild(clearBtn);

        canvas.parentNode.insertBefore(container, canvas);
    };

    const setPattern = name => {
        clearGrid();
        const originY = Math.floor(rows / 2), originX = Math.floor(cols / 2);
        const list = patternCoordinates(name);
        list.forEach(([dy, dx]) => {
            const y = originY + dy;
            const x = originX + dx;
            if (y >= 0 && y < rows && x >= 0 && x < cols) grid[y][x] = { age: 0 };
        });
    };

    const patternCoordinates = name => {
        switch (name) {
            case 'glider':
                return [
                    [0, 1], [1, 2], [2, 0], [2, 1], [2, 2]
                ];
            case 'blinker':
                return [
                    [0, 0], [0, 1], [0, 2]
                ];
            case 'pulsar':
                const coords = [];
                const offs = [2, 3, 4, 9, 10, 11];
                offs.forEach(dy => offs.forEach(dx => {
                    if (dy === 2 && dx === 2) return;
                    coords.push([dy, dx]);
                    coords.push([dy, -dx]);
                    coords.push([-dy, dx]);
                    coords.push([-dy, -dx]);
                }));
                return coords;
            case 'gospergun':
                const g = [
                    [5, 1], [5, 2], [6, 1], [6, 2],
                    [5, 11], [6, 11], [7, 11],
                    [4, 12], [8, 12],
                    [3, 13], [9, 13],
                    [3, 14], [9, 14],
                    [6, 15],
                    [4, 16], [8, 16],
                    [5, 17], [6, 17], [7, 17],
                    [6, 18],
                    [3, 21], [4, 21], [5, 21],
                    [3, 22], [4, 22], [5, 22],
                    [3, 23], [4, 23], [5, 23],
                    [2, 25], [6, 25],
                    [1, 35], [2, 35], [6, 35], [7, 35]
                ];
                // shift pattern to fit into grid
                const mx = Math.floor(Math.max(...g.map(c=>c[0]))/2);
                const my = Math.floor(Math.max(...g.map(c=>c[1]))/2);
                return g.map(c => [c[0]-mx, c[1]-my]);
            default:
                return [];
        }
    };

    const randomize = () => {
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                grid[y][x] = Math.random() < 0.3 ? { age: 0 } : null;
                fadeGrid[y][x] = 0;
            }
        }
    };

    const clearGrid = () => {
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                grid[y][x] = null;
                fadeGrid[y][x] = 0;
            }
        }
    };

    const countNeighbors = (y, x) => {
        let count = 0;
        for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
                if (dy === 0 && dx === 0) continue;
                const ny = y + dy, nx = x + dx;
                if (ny >= 0 && ny < rows && nx >= 0 && nx < cols && grid[ny][nx]) count++;
            }
        }
        return count;
    };

    const step = () => {
        const newGrid = Array.from({ length: rows }, () => Array(cols).fill(null));
        const newFadeGrid = fadeGrid.map(row => row.slice());
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                const alive = grid[y][x] !== null;
                const age = alive ? grid[y][x].age : 0;
                const neighbors = countNeighbors(y, x);
                let willLive = false;
                if (alive) {
                    if (neighbors === 2 || neighbors === 3) willLive = true;
                } else {
                    if (neighbors === 3) willLive = true;
                }
                if (willLive) {
                    newGrid[y][x] = { age: alive ? age + 1 : 0 };
                } else if (alive) {
                    newFadeGrid[y][x] = 1;
                }
            }
        }
        grid = newGrid;
        fadeGrid = newFadeGrid;
    };

    const render = () => {
        ctx.clearRect(0, 0, w, h);
        ctx.textBaseline = 'top';
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                const cell = grid[y][x];
                const fade = fadeGrid[y][x];
                if (cell) {
                    const emoji = getEmoji(cell.age);
                    ctx.fillText(emoji, x * cellSize, y * cellSize);
                } else if (fade > 0) {
                    ctx.globalAlpha = fade;
                    ctx.fillText('💀', x * cellSize, y * cellSize);
                    ctx.globalAlpha = 1;
                }
            }
        }
    };

    let msPerGen = 1000 / 5;
    let lastTime = performance.now();
    const loop = (t) => {
        const delta = t - lastTime;
        lastTime = t;
        while (delta >= msPerGen) {
            step();
            msPerGen = 1000 / Math.max(1, document.querySelector('input[type=range]').value);
        }
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                const fade = fadeGrid[y][x];
                if (fade > 0) {
                    fadeGrid[y][x] = Math.max(0, fade - delta / 200);
                }
            }
        }
        render();
        requestAnimationFrame(loop);
    };

    canvas.addEventListener('mousedown', event => {
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((event.clientX - rect.left) / cellSize);
        const y = Math.floor((event.clientY - rect.top) / cellSize);
        if (x >= 0 && x < cols && y >= 0 && y < rows) {
            if (grid[y][x]) {
                grid[y][x] = null;
                fadeGrid[y][x] = 1;
            } else {
                grid[y][x] = { age: 0 };
                fadeGrid[y][x] = 0;
            }
        }
    });

    createUI();
    requestAnimationFrame(loop);
}

Solution B: function initGameOfLife(canvasId){const canvas=document.getElementById(canvasId);if(!canvas)return;const ctx=canvas.getContext('2d');const width=canvas.width;const height=canvas.height;const cellSize=10;const cols=Math.floor(width/cellSize);const rows=Math.floor(height/cellSize);let grid=Array.from({length:rows},()=>Array.from({length:cols},()=>({alive:false,age:0,fade:0})));let nextGrid=Array.from({length:rows},()=>Array.from({length:cols},()=>({alive:false,age:0,fade:0})));const emojis=['🌱','🌿','🌳','🌲','🎄'];const maxFade=500;let lastTime=0;let acc=0;let speed=5;function draw(){ctx.clearRect(0,0,width,height);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${cellSize-2}px sans-serif`;for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){const cell=grid[y][x];if(cell.alive){let e=emojis[Math.min(emojis.length-1,Math.floor(cell.age/2))];ctx.globalAlpha=1;ctx.fillText(e,x*cellSize+cellSize/2,y*cellSize+cellSize/2);}else if(cell.fade>0){let e='💀';ctx.globalAlpha=cell.fade/maxFade;ctx.fillText(e,x*cellSize+cellSize/2,y*cellSize+cellSize/2);}}}ctx.globalAlpha=1;}function step(){for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){let alive=grid[y][x].alive;let neighbors=0;for(let dy=-1;dy<=1;dy++){for(let dx=-1;dx<=1;dx++){if(dx===0&&dy===0)continue;let nx=(x+dx+cols)%cols;let ny=(y+dy+rows)%rows;if(grid[ny][nx].alive)neighbors++;}}let next=grid[y][x];if(alive){if(neighbors<2||neighbors>3){next.alive=false;next.age=0;next.fade=maxFade;}else{next.alive=true;next.age=grid[y][x].age+1;next.fade=0;}}else{if(neighbors===3){next.alive=true;next.age=0;next.fade=0;}}nextGrid[y][x]=Object.assign({},next);} }let temp=grid;grid=nextGrid;nextGrid=temp;}function loop(timestamp){if(!lastTime)lastTime=timestamp;let delta=timestamp-lastTime;lastTime=timestamp;acc+=delta;if(acc>=1000/speed){step();acc=0;}draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);function toggleCell(mx,my){const rect=canvas.getBoundingClientRect();const x=Math.floor((mx-rect.left)/cellSize);const y=Math.floor((my-rect.top)/cellSize);if(x<0||x>=cols||y<0||y>=rows)return;let cell=grid[y][x];cell.alive=!cell.alive;cell.age=cell.alive?0:0;cell.fade=cell.alive?0:maxFade;}canvas.addEventListener('click',e=>toggleCell(e.clientX,e.clientY));function clearGrid(){for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)grid[y][x]={alive:false,age:0,fade:0};}function randomize(){for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)grid[y][x]={alive:Math.random()<0.2,age:0,fade:0};}function loadPattern(pattern){clearGrid();const offsetX=Math.floor(cols/2);const offsetY=Math.floor(rows/2);pattern.forEach(([px,py])=>{let x=offsetX+px;let y=offsetY+py;if(x>=0&&x<cols&&y>=0&&y<rows)grid[y][x].alive=true;});}const patterns={Glider:[[1,0],[2,1],[0,2],[1,2],[2,2]],Blinker:[[0,0],[1,0],[2,0]],GosperGun:[[0,4],[0,5],[1,4],[1,5],[10,4],[10,5],[10,6],[11,3],[11,7],[12,2],[12,8],[13,2],[13,8],[14,5],[15,3],[15,4],[15,5],[15,6],[15,7],[16,4],[16,5],[17,5],[20,2],[20,3],[20,4],[21,2],[21,3],[21,4],[22,1],[22,5],[24,0],[24,1],[24,5],[24,6],[34,2],[34,3],[35,2],[35,3]],Pulsar:[[2,0],[3,0],[4,0],[6,0],[7,0],[8,0],[0,2],[5,2],[7,2],[9,2],[0,3],[5,3],[7,3],[9,3],[0,4],[5,4],[7,4],[9,4],[2,5],[3,5],[4,5],[6,5],[7,5],[8,5],[2,7],[3,7],[4,7],[6,7],[7,7],[8,7],[0,9],[5,9],[7,9],[9,9],[0,10],[5,10],[7,10],[9,10],[0,11],[5,11],[7,11],[9,11],[2,12],[3,12],[4,12],[6,12],[7,12],[8,12]]};const ui=document.createElement('div');ui.style.marginTop='10px';const patternSelect=document.createElement('select');Object.keys(patterns).forEach(name=>{const opt=document.createElement('option');opt.value=name;opt.textContent=name;patternSelect.appendChild(opt);});patternSelect.addEventListener('change',e=>loadPattern(patterns[e.target.value]));ui.appendChild(patternSelect);const speedLabel=document.createElement('label');speedLabel.textContent=' Speed:';ui.appendChild(speedLabel);const speedSlider=document.createElement('input');speedSlider.type='range';speedSlider.min='1';speedSlider.max='10';speedSlider.value='5';speedSlider.addEventListener('input',e=>{speed=parseInt(e.target.value,10);});ui.appendChild(speedSlider);const randomBtn=document.createElement('button');randomBtn.textContent='Randomize';randomBtn.onclick=randomize;ui.appendChild(randomBtn);const clearBtn=document.createElement('button');clearBtn.textContent='Clear';clearBtn.onclick=clearGrid;ui.appendChild(clearBtn);canvas.parentNode.insertBefore(ui,canvas.nextSibling);}

